// Normaliza el dominio y marca duplicados y bloqueados, para descartarlos con motivo
const bloqueo = String($('B · Leer Config').first().json.lista_bloqueo || '')
  .split(/[,\n]/).map(s => s.trim().toLowerCase()).filter(Boolean);

function raiz(valor) {
  let d = String(valor || '').trim().toLowerCase();
  d = d.replace(/^https?:\/\//, '').replace(/[\/?#:].*$/, '').replace(/^www\./, '');
  const partes = d.split('.');
  const sld = partes[partes.length - 2] || '';
  const tld = partes[partes.length - 1] || '';
  // co.uk, com.br, com.ar: la raíz tiene tres trozos
  if (partes.length > 2 && tld.length === 2 && ['co', 'com', 'org', 'net', 'gov', 'gob', 'edu', 'ac'].includes(sld)) return partes.slice(-3).join('.');
  return partes.slice(-2).join('.');
}

// La primera aparición de cada raíz se queda; las siguientes son duplicados
const vistos = new Set();

return $input.all().map(item => {
  const dominio_raiz = raiz(item.json.dominio_raiz);
  const es_duplicado = vistos.has(dominio_raiz);
  vistos.add(dominio_raiz);
  return { json: { ...item.json, dominio_raiz, es_duplicado, en_bloqueo: bloqueo.includes(dominio_raiz) } };
});

// Cruza la respuesta de Ahrefs con los prospectos: ya_enlaza = true si su raíz aparece
function raiz(valor) {
  let d = String(valor || '').trim().toLowerCase();
  d = d.replace(/^https?:\/\//, '').replace(/[\/?#:].*$/, '').replace(/^www\./, '');
  const partes = d.split('.');
  const sld = partes[partes.length - 2] || '';
  const tld = partes[partes.length - 1] || '';
  if (partes.length > 2 && tld.length === 2 && ['co', 'com', 'org', 'net', 'gov', 'gob', 'edu', 'ac'].includes(sld)) return partes.slice(-3).join('.');
  return partes.slice(-2).join('.');
}
const respuesta = $('B · Ahrefs: quién ya enlaza al negocio').first().json;
const enlazan = new Set((respuesta.refdomains || []).map(r => raiz(r.domain)));

return $('B · Prospectos limpios').all().map(i => ({
  json: { ...i.json, ya_enlaza: enlazan.has(i.json.dominio_raiz) }
}));

// Junta todos los prospectos en UN solo item para hacer UNA sola llamada a Ahrefs
const prospectos = $input.all().map(i => i.json);
return [{ json: {
  prospectos,
  targets: prospectos.map(p => ({ url: p.dominio_raiz, mode: 'subdomains', protocol: 'both' }))
} }];

// Vuelve a separar la respuesta en un item por dominio, con las métricas en las columnas de la tabla
const prospectos = $('B · Preparar lote Ahrefs').first().json.prospectos;
const targets = $input.first().json.targets || [];

return prospectos.map((p, i) => {
  const t = targets.find(x => x.index === i) || targets[i] || {};
  const dr = Number(t.domain_rating || 0);
  const trafico = Number(t.org_traffic || 0);
  const refdomains = Number(t.refdomains || 0);
  const enlazados = Number(t.linked_domains || 0);
  return { json: {
    id: p.id,
    dominio_raiz: p.dominio_raiz,
    dr,
    trafico_organico: trafico,
    dominios_referencia: refdomains,
    dominios_enlazados: enlazados,
    ratio_enlazados: refdomains > 0 ? Number((enlazados / refdomains).toFixed(2)) : 999
  } };
});

// Clasifica la web en el segmento de marketing: gran prensa (no se toca), pequeña prensa (lista de PR) o pyme (visto bueno y email)
const cfg = $('B · Leer Config').first().json;
const d = $input.item.json;
const num = v => (v === null || v === undefined || v === '') ? null : Number(v);
const granDr = num(cfg.gran_prensa_dr_min);
const granTrafico = num(cfg.gran_prensa_trafico_min);
const pymeMin = num(cfg.pyme_dr_min);
const pymeMax = num(cfg.pyme_dr_max);
const tipo = String(d.tipo_sitio || '').toLowerCase();

let segmento;
// Sin umbrales en la config, todo va al visto bueno como antes
if (granDr === null && granTrafico === null && pymeMin === null && pymeMax === null) segmento = 'sin_segmentar';
else if (tipo === 'medio') {
  const grande = (granDr !== null && d.dr >= granDr) || (granTrafico !== null && d.trafico_organico >= granTrafico);
  segmento = grande ? 'gran_prensa' : 'pequena_prensa';
} else if (tipo === 'empresa') {
  segmento = (d.dr >= (pymeMin ?? 0) && d.dr <= (pymeMax ?? 100)) ? 'pyme' : 'empresa_fuera_rango';
} else segmento = 'otro';

const destino = {
  pyme: { estado: 'pendiente_aprobacion', motivo: '' },
  sin_segmentar: { estado: 'pendiente_aprobacion', motivo: '' },
  pequena_prensa: { estado: 'lista_pr', motivo: '' },
  gran_prensa: { estado: 'descartado', motivo: 'gran_prensa' },
  empresa_fuera_rango: { estado: 'descartado', motivo: 'fuera_de_segmento' },
  otro: { estado: 'descartado', motivo: 'fuera_de_segmento' }
}[segmento];

return { json: { ...d, segmento, estado: destino.estado, motivo: destino.motivo, al_visto_bueno: destino.estado === 'pendiente_aprobacion' } };

