// Explica en una palabra por qué no pasa, para que se lea en la tabla
const cfg = $('B · Leer Config').first().json;
const d = $input.item.json;
const motivos = [];
if (d.dr < cfg.umbral_dr_min) motivos.push('dr_bajo');
if (d.trafico_organico < cfg.umbral_trafico_min) motivos.push('trafico_bajo');
if (d.dominios_referencia < cfg.umbral_refdomains_min) motivos.push('pocos_refdomains');
if (d.ratio_enlazados > cfg.umbral_ratio_max) motivos.push('ratio_granja');
if (d.dr >= cfg.granja_dr && d.trafico_organico < cfg.granja_trafico) motivos.push('dr_sin_trafico');
return { json: { id: d.id, motivo: motivos.join('+') || 'umbrales' } };

// Junta las webs que esperan visto bueno en un solo formulario: una casilla por web y sus datos a la vista
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const vistos = new Set();
const candidatos = [];
for (const item of $input.all()) {
  const c = item.json;
  if (!c.id || vistos.has(c.id)) continue;
  vistos.add(c.id);
  candidatos.push({
    id: c.id,
    dominio_raiz: c.dominio_raiz,
    idioma: c.idioma || '',
    origen: c.origen || 'pendiente',
    segmento: c.segmento || '',
    dr: c.dr ?? '',
    trafico: c.trafico_organico ?? '',
    relevancia: c.relevancia ?? '',
    motivo: c.motivo_relevancia || '',
    articulo_titulo: c.articulo_titulo || '',
    articulo_url: c.articulo_url || ''
  });
}

const filas = candidatos.map(c =>
  '<tr><td><b>' + esc(c.dominio_raiz) + '</b></td><td>' + esc(c.segmento || '—') + '</td><td>' + esc(c.dr) + '</td><td>' + esc(c.trafico) + '</td><td>' + esc(c.relevancia) + '/10</td><td>' + esc(c.idioma) + '</td><td>' + esc(c.motivo) + '</td><td>' +
  (c.articulo_url ? '<a href="' + esc(c.articulo_url) + '" target="_blank">' + esc(c.articulo_titulo || c.articulo_url) + '</a>' : '') + '</td></tr>'
).join('');
const tabla = '<table><tr><th>Web</th><th>Segmento</th><th>DR</th><th>Tráfico</th><th>Relevancia</th><th>Idioma</th><th>Por qué encaja</th><th>Artículo</th></tr>' + filas + '</table>';

const formulario = [
  { fieldType: 'html', elementName: 'datos', html: tabla },
  { fieldLabel: 'Webs que apruebas', fieldType: 'checkbox', fieldOptions: { values: candidatos.map(c => ({ option: c.dominio_raiz })) } },
  { fieldLabel: 'Las que no marques', fieldType: 'radio', requiredField: true, fieldOptions: { values: [{ option: 'Rechazarlas' }, { option: 'Dejarlas para mañana' }] } }
];

const mensaje = ':white_check_mark: *' + candidatos.length + ' webs esperan tu visto bueno antes de gastar créditos de Hunter*\n' +
  candidatos.map(c => '• ' + c.dominio_raiz + (c.segmento ? ' · ' + c.segmento : '') + ' · DR ' + c.dr + ' · relevancia ' + c.relevancia + '/10 · ' + c.idioma).join('\n') +
  '\nSi nadie responde en 20 horas, vuelven a salir mañana.';

return [{ json: { candidatos, formulario, mensaje } }];

// Traduce la respuesta del formulario a una decisión por web: aprobado, rechazado o sin_respuesta
const candidatos = $('B · Preparar formulario').first().json.candidatos;
const datos = $input.first().json.data || {};
const valores = Object.values(datos);

// La pregunta obligatoria sobre las no marcadas dice si alguien respondió
const resto = datos['Las que no marques'] ?? valores.find(v => typeof v === 'string' && /rechaz|mañana/i.test(v));
const respondio = Boolean(resto);
const rechazarResto = respondio && /rechaz/i.test(String(resto));

let marcadas = datos['Webs que apruebas'] ?? valores.find(v => Array.isArray(v)) ?? [];
if (!Array.isArray(marcadas)) marcadas = String(marcadas).split(',').map(s => s.trim()).filter(Boolean);

return candidatos.map(c => {
  let decision = 'sin_respuesta';
  if (respondio && marcadas.includes(c.dominio_raiz)) decision = 'aprobado';
  else if (rechazarResto) decision = 'rechazado';
  return { json: { id: c.id, dominio_raiz: c.dominio_raiz, idioma: c.idioma, origen: c.origen, decision } };
});

// Freno de Hunter: marca qué dominios caben con los créditos que quedan este mes
const cfg = $('B · Leer Config').first().json;
const cuenta = $input.first().json;
const creditos = (cuenta.data && cuenta.data.requests && cuenta.data.requests.credits) || {};
const restantes = Number(creditos.remaining ?? creditos.available ?? 0);

// Cada dominio cuesta como mucho: 1 crédito por email encontrado + 0,5 por la verificación
const emailsPorDominio = Number(cfg.hunter_emails_por_dominio || 2);
const costePorDominio = emailsPorDominio + 0.5;
const caben = Math.floor(restantes / costePorDominio);

// La cola ya viene ordenada: primero los pendientes de días anteriores
const cola = $('B · Cola para Hunter').all();

return cola.map((item, i) => ({ json: {
  id: item.json.id,
  dominio_raiz: item.json.dominio_raiz,
  idioma: item.json.idioma,
  origen: item.json.origen || 'pendiente',
  cabe: i < caben,
  creditos_restantes: restantes,
  coste_por_dominio: costePorDominio,
  caben_hoy: caben,
  en_cola: cola.length
} }));

// Primero los que Hunter ya tiene verificados; después, personas de contenido, prensa o alianzas; después, el de más confianza
const dominio = $('B · ¿Cabe en Hunter?').item.json;
const todos = ($input.item.json.data && $input.item.json.data.emails) || [];
// Hunter ya dice en la búsqueda si un email está verificado: los inválidos se quitan aquí, sin gastar la verificación
const estado = e => String((e.verification && e.verification.status) || '').toLowerCase();
const emails = todos.filter(e => estado(e) !== 'invalid');
const nota = e => estado(e) === 'valid' ? 2 : (estado(e) === 'accept_all' ? 1 : 0);
const cargosPreferidos = /editor|redac|content|contenido|prensa|press|comunic|marketing|seo|colabor|partner|alianza/i;

const ordenados = [...emails].sort((a, b) => {
  if (nota(a) !== nota(b)) return nota(b) - nota(a);
  const pa = cargosPreferidos.test(a.position || '') ? 1 : 0;
  const pb = cargosPreferidos.test(b.position || '') ? 1 : 0;
  if (pa !== pb) return pb - pa;
  return (b.confidence || 0) - (a.confidence || 0);
});
const mejor = ordenados[0] || {};

return { json: {
  id: dominio.id,
  dominio_raiz: dominio.dominio_raiz,
  idioma: dominio.idioma,
  email: mejor.value || '',
  email_nombre: [mejor.first_name, mejor.last_name].filter(Boolean).join(' '),
  email_cargo: mejor.position || '',
  email_confianza: mejor.confidence || 0,
  emails_encontrados: todos.length
} };

