// Arma el aviso semanal para PR con las webs de pequeña prensa que aún no se le han pasado
const cfg = $('A · Leer Config').first().json;
const webs = $input.all().map(i => i.json).filter(w => w.id && w.dominio_raiz);
if (!webs.length) return [];
const miles = n => String(Math.round(Number(n || 0))).replace(/\B(?=(\d{3})+(?!\d))/g, '.');

const lineas = [
  ':newspaper: :rotating_light: *LISTA PARA PR · ' + cfg.negocio_nombre + ' · ' + webs.length + ' webs de pequeña prensa* :rotating_light:',
  '_Medios pequeños y afines que la automatización no contacta: son para la lista de PR orgánico._',
  ...webs.map(w => '• *' + w.dominio_raiz + '* · DR ' + (w.dr ?? '?') + ' · ' + miles(w.trafico_organico) + ' visitas/mes · ' + (w.idioma || '?') + (w.motivo_relevancia ? ' · ' + w.motivo_relevancia : '')),
  ':white_check_mark: Quedan marcadas como avisadas: la semana que viene solo saldrán las nuevas.'
];

return [{ json: { texto: lineas.join('\n'), ids: webs.map(w => w.id) } }];

// Un item por competidor de la config. Si no hay ninguno, un item vacío para que la fuente termine igualmente
const cfg = $('A · Leer Config').first().json;
const competidores = String(cfg.competidores || '').split(/[,\n]/).map(s => s.trim().toLowerCase()).filter(Boolean);
if (!competidores.length) return [{ json: { competidor: '' } }];
return competidores.map(competidor => ({ json: { competidor } }));

// Cuenta a cuántos competidores enlaza cada web y se queda con las que enlazan a 2 o más
function raiz(valor) {
  let d = String(valor || '').trim().toLowerCase();
  d = d.replace(/^https?:\/\//, '').replace(/[\/?#:].*$/, '').replace(/^www\./, '');
  const partes = d.split('.');
  const sld = partes[partes.length - 2] || '';
  const tld = partes[partes.length - 1] || '';
  // co.uk, com.br, com.ar: la raíz tiene tres trozos
  if (partes.length > 2 && tld.length === 2 && ['co', 'com', 'org', 'net', 'gov', 'gob', 'edu', 'ac'].includes(sld)) return partes.slice(-3).join('.');
  return partes.slice(-2).join('.');
}

const conteo = {};
let llamadas = 0, errores = 0, coste = 0;
for (const item of $input.all()) {
  const r = item.json;
  if (r.error) { errores++; continue; }
  if (!Array.isArray(r.refdomains)) continue;
  llamadas++;
  // Coste aproximado: 3 unidades por fila (dominio, DR y el filtro dofollow), mínimo 50 por llamada
  coste += Math.max(50, r.refdomains.length * 3);
  const vistos = new Set();
  for (const d of r.refdomains) {
    const dominio = raiz(d.domain);
    if (!dominio || vistos.has(dominio)) continue;
    vistos.add(dominio);
    if (!conteo[dominio]) conteo[dominio] = { dominio, n_competidores: 0, dr: 0 };
    conteo[dominio].n_competidores++;
    conteo[dominio].dr = Math.max(conteo[dominio].dr, Number(d.domain_rating || 0));
  }
}

const dominios = Object.values(conteo).filter(c => c.n_competidores >= 2);
return [{ json: { fuente: 'competidor', dominios, llamadas, errores, coste_ahrefs: coste, busquedas: 0 } }];

// Busca el nombre del negocio fuera de su propio dominio, en las tres primeras páginas de Google
const cfg = $('A · Leer Config').first().json;
const q = '"' + cfg.negocio_nombre + '" -site:' + cfg.negocio_dominio;
return [0, 10, 20].map(start => ({ json: { q, start } }));

// Saca la web de cada resultado de Google
const dominios = [];
let busquedas = 0, errores = 0;
for (const item of $input.all()) {
  const r = item.json;
  if (r.error && !r.search_metadata) { errores++; continue; }
  if (!r.search_metadata) continue;
  busquedas++;
  for (const res of (r.organic_results || [])) {
    if (res.link) dominios.push({ dominio: res.link });
  }
}
return [{ json: { fuente: 'mencion', dominios, llamadas: busquedas, errores, coste_ahrefs: 0, busquedas } }];

// Una búsqueda por cada consulta de la config, separadas por |. Si no hay ninguna, un item vacío
const cfg = $('A · Leer Config').first().json;
const consultas = String(cfg.busquedas_serpapi || '').split('|').map(s => s.trim()).filter(Boolean);
if (!consultas.length) return [{ json: { q: '' } }];
return consultas.map(q => ({ json: { q } }));

// Saca la web de cada resultado de Google
const dominios = [];
let busquedas = 0, errores = 0;
for (const item of $input.all()) {
  const r = item.json;
  if (r.error && !r.search_metadata) { errores++; continue; }
  if (!r.search_metadata) continue;
  busquedas++;
  for (const res of (r.organic_results || [])) {
    if (res.link) dominios.push({ dominio: res.link });
  }
}
return [{ json: { fuente: 'serpapi', dominios, llamadas: busquedas, errores, coste_ahrefs: 0, busquedas } }];

// Normaliza cada web, quita lo que nunca se contacta y ordena por prioridad de la fuente
const cfg = $('A · Leer Config').first().json;
function raiz(valor) {
  let d = String(valor || '').trim().toLowerCase();
  d = d.replace(/^https?:\/\//, '').replace(/[\/?#:].*$/, '').replace(/^www\./, '');
  const partes = d.split('.');
  const sld = partes[partes.length - 2] || '';
  const tld = partes[partes.length - 1] || '';
  // co.uk, com.br, com.ar: la raíz tiene tres trozos
  if (partes.length > 2 && tld.length === 2 && ['co', 'com', 'org', 'net', 'gov', 'gob', 'edu', 'ac'].includes(sld)) return partes.slice(-3).join('.');
  return partes.slice(-2).join('.');
}
const lista = s => String(s || '').split(/[,\n]/).map(x => raiz(x)).filter(Boolean);
const propio = raiz(cfg.negocio_dominio);
const bloqueo = new Set(lista(cfg.lista_bloqueo));
const competidores = new Set(lista(cfg.competidores));

// Plataformas donde no hay una redacción a la que escribir
const plataformas = new Set([
  // Redes, buscadores y grandes servicios
  'google.com', 'youtube.com', 'facebook.com', 'instagram.com', 'twitter.com', 'x.com', 'linkedin.com', 'tiktok.com', 'reddit.com', 'pinterest.com', 'quora.com', 't.me', 'telegram.me', 'telegram.org', 'whatsapp.com', 'discord.com', 'discord.gg', 'threads.net', 'bsky.app', 'apple.com', 'microsoft.com', 'amazon.com', 'bing.com', 'yahoo.com', 'duckduckgo.com', 'ya.ru', 'deviantart.com', 'reverso.net', 'uptodown.com', 'setapp.com',
