const zona = partes[2] || 'Europe/Madrid';
const letras = { L: 1, M: 2, X: 3, J: 4, V: 5, S: 6, D: 7 };
const minutos = s => { const [h, m] = String(s || '').split(':').map(Number); return (h || 0) * 60 + (m || 0); };
const ahora = $now.setZone(zona);
