    fila.rel = a.rel || ''; fila.anchor = a.anchor || ''; fila.indexable = a.indexable !== false;
    avisos.push('• :warning: No se pudo leer ' + r.url_origen + ' (' + r.fallo + '). Se reintenta la próxima semana');
  } else if (vivoOk && fila.estado !== 'vivo') {
