const esHoy = f => Boolean(f) && DateTime.fromISO(String(f)).setZone(zona) >= inicioHoy;

const mensajes = filas('G · Leer mensajes');
const contactos = filas('G · Leer contactos');
const dominios = filas('G · Leer dominios');
const log = filas('G · Leer log');
const porEstado = (lista, estado) => lista.filter(x => x.estado === estado).length;

const enviadosHoy = mensajes.filter(m => m.direccion === 'salida' && ['outreach', 'follow_up'].includes(m.tipo) && esHoy(m.updatedAt)).length;
const borradoresHoy = mensajes.filter(m => m.direccion === 'salida' && esHoy(m.createdAt)).length;
const respuestasHoy = mensajes.filter(m => m.direccion === 'entrada' && esHoy(m.createdAt));
const tipos = {};
for (const r of respuestasHoy) { const c = r.clasificacion || 'sin clasificar'; tipos[c] = (tipos[c] || 0) + 1; }
const cualificadosHoy = dominios.filter(d => d.estado === 'cualificado' && esHoy(d.updatedAt)).length;

// El gasto se agrupa por servicio, porque cada uno se mide en su unidad
const gasto = {};
for (const l of log.filter(l => esHoy(l.createdAt))) {
  const u = /ahrefs/.test(l.accion) ? 'unidades de Ahrefs' : /hunter/.test(l.accion) ? 'créditos de Hunter' : /serpapi/.test(l.accion) ? 'búsquedas de SerpAPI' : null;
  if (u) gasto[u] = (gasto[u] || 0) + Number(l.coste_estimado || 0);
}
const gastoTxt = Object.entries(gasto).map(([u, n]) => n + ' ' + u).join(' · ') || 'nada';

const lineas = [
  ':bar_chart: *Resumen diario · ' + cfg.negocio_nombre + ' · ' + ahora.toFormat('dd/MM') + '*',
  '• Enviados hoy: ' + enviadosHoy + ' de ' + Number(cfg.limite_diario || 0) + ' (borradores del día: ' + borradoresHoy + ')',
  '• Respuestas hoy: ' + respuestasHoy.length + (respuestasHoy.length ? ' (' + Object.entries(tipos).map(([t, n]) => t + ' ' + n).join(', ') + ')' : ''),
  '• Cualificados nuevos hoy: ' + cualificadosHoy,
  '• Esperando: ' + porEstado(dominios, 'prospecto') + ' en cola · ' + porEstado(dominios, 'pendiente_aprobacion') + ' por aprobar · ' + porEstado(dominios, 'pendiente_email') + ' sin créditos de Hunter',
  '• Contactos: ' + porEstado(contactos, 'listo_para_enviar') + ' listos · ' + porEstado(contactos, 'pendiente_revision') + ' en revisión · ' + porEstado(contactos, 'negociando') + ' negociando',
  '• Gasto de hoy: ' + gastoTxt
];

// Los viernes, KPIs acumulados leyendo el estado de las tablas (si se limpian mensajes antiguos, serán parciales)
if (ahora.weekday === 5) {
  const enviados = mensajes.filter(m => m.direccion === 'salida' && m.tipo === 'outreach').length;
  // La tasa cuenta personas, no mensajes. Fuera de oficina y rebotes no son respuesta
  const escritos = new Set(mensajes.filter(m => m.direccion === 'salida' && m.tipo === 'outreach').map(m => Number(m.contacto_id)));
  const entradas = mensajes.filter(m => m.direccion === 'entrada');
  const respondieron = new Set(entradas.filter(m => escritos.has(Number(m.contacto_id)) && !['fuera_oficina', 'rebote'].includes(m.clasificacion)).map(m => Number(m.contacto_id)));
  const interesados = new Set(entradas.filter(m => ['interesado', 'pide_info'].includes(m.clasificacion)).map(m => Number(m.contacto_id)));
  const conseguidos = contactos.filter(c => c.estado === 'conseguido');
  const dominiosPorId = {}; for (const d of dominios) dominiosPorId[d.id] = d;
  const drs = conseguidos.map(c => Number((dominiosPorId[c.dominio_id] || {}).dr || 0)).filter(Boolean);
  const drMedio = drs.length ? Math.round(drs.reduce((s, n) => s + n, 0) / drs.length) : 0;
  lineas.push('', ':chart_with_upwards_trend: *KPIs (acumulado de las tablas)*',
    '• Primeros emails enviados: ' + enviados,
    '• Tasa de respuesta: ' + (escritos.size ? Math.round(100 * respondieron.size / escritos.size) + ' % (' + respondieron.size + ' de ' + escritos.size + ' contactos)' : 'sin envíos') + ' · con interés: ' + interesados.size,
    '• Backlinks conseguidos: ' + conseguidos.length + (drs.length ? ' (DR medio ' + drMedio + ')' : ''));
}

return [{ json: { texto: lineas.join('\n') } }];

// Un item por competidor de la config. Si no hay ninguno, un item vacío para que la fuente termine igualmente
const cfg = $('A · Leer Config').first().json;
const competidores = String(cfg.competidores || '').split(/[,\n]/).map(s => s.trim().toLowerCase()).filter(Boolean);
if (!competidores.length) return [{ json: { competidor: '' } }];
return competidores.map(competidor => ({ json: { competidor } }));

// Webs que enlazaban a páginas rotas de los competidores: su enlace ya no les sirve y se les puede proponer algo vivo
function raiz(valor) {
  let d = String(valor || '').trim().toLowerCase();
  d = d.replace(/^https?:\/\//, '').replace(/[\/?#:].*$/, '').replace(/^www\./, '');
  const partes = d.split('.');
  const sld = partes[partes.length - 2] || '';
  const tld = partes[partes.length - 1] || '';
  // co.uk, com.br, com.ar: la raíz tiene tres trozos
  if (partes.length > 2 && tld.length === 2 && ['co', 'com', 'org', 'net', 'gov', 'gob', 'edu', 'ac'].includes(sld)) return partes.slice(-3).join('.');
  return partes.slice(-2).join('.');
}

const conteo = {};
let llamadas = 0, errores = 0, coste = 0;
for (const item of $input.all()) {
  const r = item.json;
  if (r.error) { errores++; continue; }
  const filas = r.brokenBacklinks || r.broken_backlinks || r.backlinks;
  if (!Array.isArray(filas)) continue;
  llamadas++;
  // Coste medido: 2 unidades por fila, mínimo 50 por llamada
  coste += Math.max(50, filas.length * 2);
  const vistos = new Set();
  for (const b of filas) {
    const dominio = raiz(b.url_from || b.domain_from);
    if (!dominio || vistos.has(dominio)) continue;
    vistos.add(dominio);
    if (!conteo[dominio]) conteo[dominio] = { dominio, dr: 0 };
    conteo[dominio].dr = Math.max(conteo[dominio].dr, Number(b.domain_rating_source || 0));
  }
}

return [{ json: { fuente: 'enlace_roto', dominios: Object.values(conteo), llamadas, errores, coste_ahrefs: coste, busquedas: 0 } }];

// Agrupa los posts del blog por idioma y quita los que ya están en el Sheet de recursos
const cfg = $('A · Leer Config').first().json;
const api = String(cfg.blog_api || '').trim();
if (!api) return [];
const idiomas = String(cfg.idiomas || 'es').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const raiz = api.split('/wp-json')[0].replace(/\/+$/, '');
const norm = u => String(u || '').trim().replace(/\/+$/, '').toLowerCase();
const yaEnSheet = new Set($('A · Leer recursos del Sheet').all().map(i => norm(i.json.url)).filter(Boolean));
const decodificar = t => String(t || '').replace(/&#(\d+);/g, (m, n) => String.fromCharCode(n))
  .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&hellip;/g, '…').replace(/<[^>]+>/g, '').trim();

// Cada página llega como una lista o como un post por item, según n8n
const posts = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]).filter(p => p && p.id && p.link);
// Sin posts es que el blog no respondió (por ejemplo, el WAF): que salte el aviso de errores
if (!posts.length) throw new Error('No se pudo leer el blog en ' + api);

const porIdioma = {};
for (const p of posts) {
  // El idioma va en la ruta (/blog/it/…); sin prefijo, es el idioma principal
  const tramo = String(p.link).slice(raiz.length).split('/').filter(Boolean)[0] || '';
  const idioma = idiomas.includes(tramo) ? tramo : idiomas[0];
  if (yaEnSheet.has(norm(p.link))) continue;
  (porIdioma[idioma] = porIdioma[idioma] || []).push({ url: p.link, titulo: decodificar(p.title && p.title.rendered), fecha: String(p.modified || '').slice(0, 10) });
}

// A la IA, los 250 más recientes de cada idioma
return Object.entries(porIdioma).map(([idioma, lista]) => {
  lista.sort((a, b) => b.fecha.localeCompare(a.fecha));
  const top = lista.slice(0, 250);
  return { json: { idioma, total: lista.length, candidatos: top.map(x => x.url + ' | ' + x.titulo).join('\n'), urls: top.map(x => x.url) } };
});

// Convierte lo que eligió la IA en filas para el Sheet: solo URLs de la lista y sin repetir
const candidatos = $('A · Blog: candidatos por idioma').all().map(i => i.json);
const filas = [];
const vistas = new Set();
$input.all().forEach((item, k) => {
  const c = candidatos[k] || {};
  const recursos = (item.json.output && item.json.output.recursos) || [];
  for (const r of recursos) {
    const url = String(r.url || '').trim();
    if (!url || !(c.urls || []).includes(url) || vistas.has(url)) continue;
    vistas.add(url);
    // "propuesto" no cuenta como activo: marketing lo cambia a "sí" si lo quiere usar
    filas.push({ json: { url, para_que_sirve: String(r.para_que_sirve || '').trim(), idiomas: c.idioma, activo: 'propuesto' } });
  }
});
return filas;

// Valida el alta del formulario, evita duplicados y la enlaza con su contacto
const f = $('F · Formulario de alta').first().json;
const campo = (...k) => { for (const x of k) if (f[x] != null && String(f[x]).trim()) return String(f[x]).trim(); return ''; };
const origen = campo('url_origen', 'Página que nos enlaza');
const destino = campo('url_destino', 'Página nuestra a la que apunta (opcional)');
const email = campo('email_contacto', 'Email del contacto (opcional)').toLowerCase();
const nota = campo('nota', 'Nota (opcional)');

// Solo direcciones web públicas: así nadie puede hacer que la rama F visite el servidor por dentro
// (sin new URL(): el entorno de los nodos Code de n8n no lo tiene)
const servidor = u => { const m = String(u || '').trim().match(/^https?:\/\/([^\/?#:\s]+)(:\d+)?([\/?#]\S*)?$/i); return m ? m[1].toLowerCase() : ''; };
const valida = u => {
  const h = servidor(u);
  return h.includes('.') && !/^[\d.]+$/.test(h) && !/(^|\.)(localhost|local|internal)$/.test(h);
};
const norm = u => String(u || '').trim().replace(/\/+$/, '').toLowerCase();
const enlaces = $('F · Leer enlaces (alta)').all().map(i => i.json).filter(e => e.id);
let error = '';
if (!valida(origen)) error = 'la página que nos enlaza no es una dirección web válida (tiene que empezar por https://)';
else if (destino && !valida(destino)) error = 'la página nuestra no es una dirección web válida';
else if (enlaces.some(e => norm(e.url_origen) === norm(origen))) error = 'ese enlace ya estaba dado de alta';

// El contacto: primero por su email; si no, por la web
const dom = servidor(origen).replace(/^www\./, '');
const contactos = $('F · Leer contactos (alta)').all().map(i => i.json).filter(c => c.id);
const c = (email && contactos.find(x => String(x.email || '').toLowerCase() === email))
  || contactos.find(x => dom && x.dominio_raiz && (dom === x.dominio_raiz || dom.endsWith('.' + x.dominio_raiz)));

const mensaje = error
  ? ':warning: *Alta de enlace rechazada*: ' + error + '\n• Enviado: ' + (origen || '(vacío)')
  : ':link: *Enlace dado de alta*\n• Página: ' + origen +
    (destino ? '\n• Apunta a: ' + destino : '') +
    '\n• Contacto: ' + (c ? c.email + ' (id ' + c.id + ')' : 'ninguno encontrado') +
    (nota ? '\n• Nota: ' + nota : '') +
    '\nLa rama F lo comprobará el domingo.';
return [{ json: { valido: !error, error, mensaje, url_origen: origen, url_destino: destino, nota, contacto_id: c ? c.id : null, dominio_id: c ? c.dominio_id : null, dominio_raiz: c ? c.dominio_raiz : dom } }];

// Borra los datos personales que ya no hacen falta (condiciones del email en frío):
// quien pidió la baja, a los 15 días; el resto de conversaciones cerradas, a los 6 meses de la última actividad
const DIA = 864e5;
const ahora = $now.toMillis();
const filas = n => { try { return $(n).all().map(i => i.json).filter(j => j.id); } catch (e) { return []; } };
const mensajes = filas('G · Leer mensajes');
const contactos = filas('G · Leer contactos');
// Estos siguen vivos: esperan turno, están en revisión o hablan con una persona
const conservar = ['listo_para_enviar', 'pendiente_revision', 'negociando', 'conseguido'];
const fecha = f => { const t = Date.parse(String(f || '')); return isNaN(t) ? 0 : t; };

const borrar = [];
const ids = new Set(contactos.map(c => Number(c.id)));
for (const c of contactos) {
  if (conservar.includes(String(c.estado || '').trim())) continue;
  const suyos = mensajes.filter(m => Number(m.contacto_id) === Number(c.id));
  const baja = suyos.some(m => m.direccion === 'entrada' && m.clasificacion === 'baja');
  const ultima = Math.max(fecha(c.fecha_ultimo_envio), fecha(c.updatedAt), ...suyos.map(m => fecha(m.updatedAt)));
  const plazo = (baja ? 15 : 180) * DIA;
  if (!ultima || ahora - ultima < plazo) continue;
  borrar.push({ json: { tabla: 'contactos', id: c.id, motivo: baja ? 'baja' : 'conversación cerrada', email: c.email } });
  for (const m of suyos) borrar.push({ json: { tabla: 'mensajes', id: m.id, motivo: 'de un contacto borrado' } });
}
// Mensajes sueltos de contactos que ya no existen, con más de 6 meses
for (const m of mensajes) {
  if (!ids.has(Number(m.contacto_id)) && fecha(m.updatedAt) && ahora - fecha(m.updatedAt) >= 180 * DIA) {
    borrar.push({ json: { tabla: 'mensajes', id: m.id, motivo: 'sin contacto' } });
  }
}
return borrar;
